// FIFA World Cup 2026 — Official squad lists (48 nations x 26 players)
// Source: FIFA official squad list PDF, June 9 2026
// Jersey numbers = position in official list (sorted by squad number)

export type WC26Position = 'GK' | 'DEF' | 'MID' | 'FWD';

export interface WC26Player {
  id: string;
  teamId: string;
  name: string;
  number: number;
  position: WC26Position;
  age: number;
  club: string;
  caps: number;
  goals: number;
  assists: number;
  isCaptain?: boolean;
  isKeyPlayer?: boolean;
  bio: string;
  wikiSlug?: string;
}

const p = (
  id: string, teamId: string, name: string, number: number,
  position: WC26Position, age: number, club: string,
  caps: number, goals: number, assists: number,
  bio: string, opts: { captain?: boolean; key?: boolean; wiki?: string } = {}
): WC26Player => ({
  id: `${teamId}_${id}`,
  teamId,
  name,
  number,
  position,
  age,
  club,
  caps,
  goals,
  assists,
  bio,
  isCaptain: opts.captain,
  isKeyPlayer: opts.key,
  wikiSlug: opts.wiki,
});

