// ── Helpers ──────────────────────────────────────────────────────────────────────────

const _playerMap = new Map(WC26_PLAYERS.map(p => [p.id, p]));
const _teamMap = new Map<string, WC26Player[]>();
for (const p of WC26_PLAYERS) {
  if (!_teamMap.has(p.teamId)) _teamMap.set(p.teamId, []);
  _teamMap.get(p.teamId)!.push(p);
}

export const getPlayersByTeam = (teamId: string): WC26Player[] =>
  _teamMap.get(teamId) ?? [];

export const getKeyPlayers = (teamId: string): WC26Player[] =>
  (getPlayersByTeam(teamId)).filter(p => p.isKeyPlayer);

export const getCaptain = (teamId: string): WC26Player | undefined =>
  (getPlayersByTeam(teamId)).find(p => p.isCaptain);

export const getPlayerById = (id: string): WC26Player | undefined =>
  _playerMap.get(id);

export const getPositionLabel = (pos: WC26Position): string =>
  ({ GK: 'Goalkeeper', DEF: 'Defender', MID: 'Midfielder', FWD: 'Forward' }[pos]);

export const getPositionColor = (pos: WC26Position): string =>
  ({ GK: '#f59e0b', DEF: '#3b82f6', MID: '#10b981', FWD: '#ef4444' }[pos]);
